const URL="https://teachablemachine.withgoogle.com/models/lkIUjeoTb/";let model,webcam,labelContainer,maxPredictions;async function init(){const e=URL+"model.json",a=URL+"metadata.json";model=await tmImage.load(e,a),maxPredictions=model.getTotalClasses(),webcam=new tmImage.Webcam(200,200,!0),await webcam.setup(),await webcam.play(),window.requestAnimationFrame(loop),document.getElementById("webcam-container").appendChild(webcam.canvas),labelContainer=document.getElementById("label-container");for(let e=0;e<maxPredictions;e++)labelContainer.appendChild(document.createElement("div"))}async function loop(){webcam.update(),await predict(),window.requestAnimationFrame(loop)}async function predict(){const e=await model.predict(webcam.canvas);for(let a=0;a<maxPredictions;a++){const t=e[a].className+": "+e[a].probability.toFixed(2);labelContainer.childNodes[a].innerHTML=t}}